import { Recipe, RecipeCostBreakdown, RecipeHealthBreakdown } from '../types';

/**
 * Generates an intelligent, realistic cost and health breakdown for any recipe
 * if one was not already generated by AI.
 */
export function generateFallbackBreakdowns(recipe: Partial<Recipe>): {
  costBreakdown: RecipeCostBreakdown;
  healthBreakdown: RecipeHealthBreakdown;
} {
  const baseCost = recipe.costEstimate || 6;
  const ingredients = recipe.ingredients || [];
  const servings = recipe.servings || 2;

  // Distribute estimated cost across ingredients
  let items = ingredients.map((ing, idx) => {
    let weight = 1;
    const cat = (ing.category || '').toLowerCase();
    const name = (ing.name || '').toLowerCase();

    if (cat.includes('meat') || cat.includes('fish') || cat.includes('seafood') || name.includes('beef') || name.includes('chicken') || name.includes('salmon')) {
      weight = 4.5;
    } else if (cat.includes('dairy') || name.includes('cheese') || name.includes('cream')) {
      weight = 2;
    } else if (cat.includes('pasta') || cat.includes('grain') || name.includes('rice') || name.includes('noodle')) {
      weight = 1.2;
    } else if (cat.includes('produce') || cat.includes('vegetable')) {
      weight = 1.5;
    } else {
      weight = 0.8;
    }

    return {
      name: `${ing.amount ? `${ing.amount} ${ing.unit || ''} ` : ''}${ing.name}`.trim(),
      weight,
      category: ing.category || 'Pantry'
    };
  });

  if (items.length === 0) {
    items = [{ name: 'Base ingredients', weight: 1, category: 'General' }];
  }

  const totalWeight = items.reduce((sum, item) => sum + item.weight, 0);
  let allocatedTotal = 0;

  const costItems = items.map((item, idx) => {
    if (idx === items.length - 1) {
      const remaining = Math.max(0.2, Number((baseCost - allocatedTotal).toFixed(2)));
      return {
        ingredient: item.name,
        cost: remaining,
        notes: item.category
      };
    }
    const itemCost = Number(Math.max(0.3, (baseCost * (item.weight / totalWeight))).toFixed(2));
    allocatedTotal += itemCost;
    return {
      ingredient: item.name,
      cost: itemCost,
      notes: item.category
    };
  });

  const finalTotal = Number(costItems.reduce((sum, i) => sum + i.cost, 0).toFixed(2));

  const costBreakdown: RecipeCostBreakdown = {
    items: costItems,
    totalCost: finalTotal,
    costPerServing: Number((finalTotal / servings).toFixed(2)),
    notes: `Estimated typical UK supermarket grocery cost for ${servings} ${servings === 1 ? 'person' : 'adults'}.`
  };

  // Health breakdown
  const healthScore = recipe.healthScore || 7;
  const isVeg = Boolean(recipe.isVegetarian || recipe.tags?.some(t => t.toLowerCase().includes('veg')));
  const isVegan = Boolean(recipe.isVegan || recipe.tags?.some(t => t.toLowerCase().includes('vegan')));
  const hasFish = Boolean(recipe.tags?.some(t => t.toLowerCase().includes('fish') || t.toLowerCase().includes('salmon')));
  const hasHighProtein = Boolean(recipe.tags?.some(t => t.toLowerCase().includes('protein')));

  const points = [];

  if (healthScore >= 8) {
    points.push({
      factor: 'Nutrient Density',
      description: 'Packed with essential vitamins, minerals, and dietary antioxidants from fresh produce.',
      impact: 'positive' as const
    });
  }

  if (hasHighProtein || healthScore >= 7) {
    points.push({
      factor: 'Protein Balance',
      description: hasFish 
        ? 'Excellent source of lean protein and heart-healthy Omega-3 fatty acids.'
        : isVeg 
        ? 'Plant-forward protein composition promoting satiety without excessive saturated fat.'
        : 'Quality protein providing essential amino acids for tissue repair and sustained satiety.',
      impact: 'positive' as const
    });
  }

  if (isVeg || isVegan) {
    points.push({
      factor: 'Dietary Fiber',
      description: 'Rich in soluble and insoluble fiber supporting gut microbiome and digestive health.',
      impact: 'positive' as const
    });
  } else {
    points.push({
      factor: 'Whole Food Composition',
      description: 'Made with minimally processed culinary ingredients rather than ultra-processed packaged meals.',
      impact: 'positive' as const
    });
  }

  // Nuance / watchout
  if (healthScore <= 7) {
    points.push({
      factor: 'Sodium & Saturated Fat',
      description: 'Moderate levels; balance with fresh greens and use reduced-salt seasoning where possible.',
      impact: 'neutral' as const
    });
  } else {
    points.push({
      factor: 'Sodium Awareness',
      description: 'Controlled sodium profile when using home-seasoned aromatics rather than commercial pastes.',
      impact: 'positive' as const
    });
  }

  const estCalories = healthScore >= 8 ? 480 : healthScore >= 7 ? 540 : 620;
  const estProtein = hasHighProtein || hasFish ? '36g' : isVeg ? '20g' : '28g';
  const estCarbs = isVeg ? '55g' : '45g';
  const estFat = hasFish ? '16g' : healthScore <= 7 ? '22g' : '14g';
  const estFiber = isVeg || healthScore >= 8 ? '7g' : '4g';

  const healthBreakdown: RecipeHealthBreakdown = {
    score: healthScore,
    summary: `${recipe.name || 'This meal'} has a health rating of ${healthScore}/10, offering ${healthScore >= 8 ? 'an exceptionally balanced and nutrient-rich' : 'a hearty, nourishing'} profile scaled for ${servings} ${servings === 1 ? 'person' : 'adults'}.`,
    points,
    macros: {
      calories: estCalories,
      protein: estProtein,
      carbs: estCarbs,
      fat: estFat,
      fiber: estFiber
    }
  };

  return { costBreakdown, healthBreakdown };
}

/**
 * Ensures a recipe has populated cost and health breakdowns.
 */
export function ensureRecipeBreakdowns(recipe: Recipe): Recipe {
  if (recipe.costBreakdown && recipe.healthBreakdown && recipe.costBreakdown.items?.length > 0) {
    return recipe;
  }

  const { costBreakdown, healthBreakdown } = generateFallbackBreakdowns(recipe);

  return {
    ...recipe,
    costBreakdown: recipe.costBreakdown || costBreakdown,
    healthBreakdown: recipe.healthBreakdown || healthBreakdown
  };
}
